/// Returns `true` if this event kind represents an entity mutation (created, updated, or removed).
pub fn is_mutation(kind: &FlatEventKind) -> bool {
    use FlatEventKind::*;
    matches!(
        kind,
        RootCreated
            | RootUpdated
            | RootRemoved
            | LibraryCreated
            | LibraryUpdated
            | LibraryRemoved
            | FolderCreated
            | FolderUpdated
            | FolderRemoved
            | NoteCreated
            | NoteUpdated
            | NoteRemoved
            | BlockCreated
            | BlockUpdated
            | BlockRemoved
            | AssetCreated
            | AssetUpdated
            | AssetRemoved
            | InkStrokeCreated
            | InkStrokeUpdated
            | InkStrokeRemoved
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_entity_event_converts_to_flat() {
        let event = Event {
            origin: Origin::DirectAccess(DirectAccessEntity::All(AllEvent::Reset)),
            ids: vec![],
            data: None,
        };
        let flat: FlatEvent = event.into();
        assert_eq!(flat.kind, FlatEventKind::Reset);
    }

    #[test]
    fn test_undo_redo_converts_to_flat() {
        let event = Event {
            origin: Origin::UndoRedo(UndoRedoEvent::Undone),
            ids: vec![],
            data: None,
        };
        let flat: FlatEvent = event.into();
        assert_eq!(flat.kind, FlatEventKind::UndoPerformed);
    }

    #[test]
    fn test_is_mutation() {
        assert!(is_mutation(&FlatEventKind::RootCreated));
        assert!(is_mutation(&FlatEventKind::RootUpdated));
        assert!(is_mutation(&FlatEventKind::RootRemoved));

        assert!(is_mutation(&FlatEventKind::LibraryCreated));
        assert!(is_mutation(&FlatEventKind::LibraryUpdated));
        assert!(is_mutation(&FlatEventKind::LibraryRemoved));

        assert!(is_mutation(&FlatEventKind::FolderCreated));
        assert!(is_mutation(&FlatEventKind::FolderUpdated));
        assert!(is_mutation(&FlatEventKind::FolderRemoved));

        assert!(is_mutation(&FlatEventKind::NoteCreated));
        assert!(is_mutation(&FlatEventKind::NoteUpdated));
        assert!(is_mutation(&FlatEventKind::NoteRemoved));

        assert!(is_mutation(&FlatEventKind::BlockCreated));
        assert!(is_mutation(&FlatEventKind::BlockUpdated));
        assert!(is_mutation(&FlatEventKind::BlockRemoved));

        assert!(is_mutation(&FlatEventKind::AssetCreated));
        assert!(is_mutation(&FlatEventKind::AssetUpdated));
        assert!(is_mutation(&FlatEventKind::AssetRemoved));

        assert!(is_mutation(&FlatEventKind::InkStrokeCreated));
        assert!(is_mutation(&FlatEventKind::InkStrokeUpdated));
        assert!(is_mutation(&FlatEventKind::InkStrokeRemoved));

        assert!(!is_mutation(&FlatEventKind::Reset));
        assert!(!is_mutation(&FlatEventKind::UndoPerformed));
        assert!(!is_mutation(&FlatEventKind::LongOperationStarted));
    }
}
